// Decide si hay que rescatar el dia de hoy.
// Devuelve un item SOLO cuando hay pieza programada y no esta publicada.
// Si no hay nada que hacer devuelve [] y el flujo termina en silencio.

const hoy = new Date().toLocaleDateString('sv-SE', { timeZone: 'Europe/Madrid' });

function leer(nombreNodo) {
  const texto = $(nombreNodo).first().json.cuerpo;
  if (typeof texto !== 'string') {
    throw new Error(nombreNodo + ': la respuesta no llego como texto. Revisa que el nodo tenga Response Format = Text y Put Output in Field = cuerpo.');
  }
  try {
    return JSON.parse(texto);
  } catch (e) {
    throw new Error(nombreNodo + ': el contenido no es JSON valido (' + e.message + ')');
  }
}

const registro = leer('Leer registro');
const calendario = leer('Leer calendario');
const pieza = calendario[hoy];

// Sin pieza programada no hay fallo que rescatar: fin de semana sin contenido
// o calendario agotado. El silencio aqui no prueba que todo vaya bien.
if (!pieza) return [];

// El cron de GitHub ya publico. Nada que hacer.
if (registro[hoy]) return [];

return [{
  json: {
    fecha: hoy,
    dia: pieza.dia ?? null,
    tema: pieza.tema ?? '(sin tema en el calendario)'
  }
}];

// Comprueba si el rescate funciono de verdad y redacta el aviso.
// Siempre devuelve un item: si el flujo ha llegado hasta aqui es porque
// hubo que intervenir, y eso se cuenta siempre.

const d = $('Decidir si hay que rescatar').first().json;
const codigo = $('Disparar el workflow').first().json.statusCode;

let publicado = false;
let idPublicacion = null;
let nota = '';

try {
  const registro = JSON.parse($('Releer registro').first().json.cuerpo);
  if (registro[d.fecha]) {
    publicado = true;
    idPublicacion = registro[d.fecha].id ?? null;
  }
} catch (e) {
  nota = 'Ademas, el registro no se pudo releer: ' + e.message;
}

const ok = codigo === 204 && publicado;

let cuerpo;
if (ok) {
  cuerpo = 'El cron de GitHub no habia publicado la pieza de hoy a las 18:00. El respaldo disparo el workflow y la publicacion salio.\n\n'
    + 'Fecha: ' + d.fecha + '\nPieza: dia ' + d.dia + ' - ' + d.tema + '\nId de la publicacion: ' + idPublicacion + '\n\n'
    + 'Si esto llega varios dias seguidos, el cron de GitHub no es fiable en este repositorio: adelanta la hora del respaldo o deja de depender de el.';
} else if (codigo !== 204) {
  cuerpo = 'El respaldo intento disparar el workflow y GitHub respondio ' + codigo + ' en vez de 204. NO se ha publicado nada.\n\n'
    + 'Fecha: ' + d.fecha + '\nPieza: dia ' + d.dia + ' - ' + d.tema + '\n\n'
    + '401 o 403: el token de n8n ha caducado o le falta permiso de Actions.\n'
    + '404: el token no ve el repositorio, o el fichero publicar.yml ha cambiado de nombre.\n'
    + 'Hay que publicar a mano hoy.';
} else {
  cuerpo = 'El respaldo disparo el workflow (GitHub acepto con 204) pero seis minutos despues el registro sigue sin la pieza de hoy. NO consta publicada.\n\n'
    + 'Fecha: ' + d.fecha + '\nPieza: dia ' + d.dia + ' - ' + d.tema + '\n\n'
    + 'Causas habituales, por orden: la variable PUBLICAR_DE_VERDAD no vale "1" y el workflow termina en modo revision sin publicar; el token de Meta ha caducado; alguna imagen no se sirve desde GitHub Pages.\n'
    + 'Mira el registro de la ejecucion en la pestana Actions.'
    + (nota ? '\n\n' + nota : '');
}

return [{
  json: {
    estado: ok ? 'OK' : 'ALERTA',
    asunto: (ok ? '[Instagram] Rescatado el dia ' : '[Instagram] FALLO: sigue sin publicarse el dia ') + d.fecha,
    cuerpo
  }
}];
